css:
.profile {
  width: 340px;
  font-family: sans-serif;
  color: #222;
}
.head {
  display: flex;
  align-items: center;
  gap: 12px;
}
.avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #ffe8d6;
  font-size: 2rem;
  text-align: center;
  line-height: 56px;
}
.meta { flex: 1; }
.meta h2 { margin: 0; }
.handle { margin: 0; color: #888; }
.follow {
  border: none;
  border-radius: 999px;
  background: #f97316;
  color: white;
  padding: 6px 16px;
  cursor: pointer;
}
.stats {
  display: flex;
  justify-content: space-between;
  list-style: none;
  padding: 0;
  margin: 12px 0;
}
.bio { margin: 0 0 12px; }
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}
.grid div {
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  background: linear-gradient(135deg, #f97316, #fbbf24);
}

.page {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 16px;
  font-family: sans-serif;
  color: #222;
}
.player {
  aspect-ratio: 16 / 9;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #111;
  color: white;
  font-size: 2.5rem;
  border-radius: 12px;
}
.main h2 { margin: 10px 0 4px; }
.sub { color: #666; margin: 0; }
.side {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.rec {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
}
.thumb {
  width: 48px;
  height: 28px;
  border-radius: 6px;
  background: linear-gradient(135deg, #fbbf24, #f97316);
}

.article {
  max-width: 46ch;
  margin: 0 auto;
  font-family: Georgia, serif;
  line-height: 1.6;
  color: #222;
}
.hero {
  height: 120px;
  border-radius: 12px;
  background: linear-gradient(135deg, #f97316, #fbbf24);
}
.article h1 { margin: 14px 0 2px; }
.byline {
  color: #999;
  font-style: italic;
  margin-top: 0;
}
.article h2 { font-size: 1.1rem; margin-bottom: 4px; }
.figure { margin: 16px 0 0; }
.swatch {
  height: 60px;
  border-radius: 8px;
  background: #ffe8d6;
}
.figure figcaption {
  font-size: 0.85rem;
  color: #777;
  margin-top: 4px;
}

.feed {
  width: 320px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-family: sans-serif;
}
.card {
  border: 1px solid #eee;
  border-radius: 12px;
  padding: 12px;
}
.card header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}
.pfp {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #ffe8d6;
  text-align: center;
  line-height: 34px;
}
.card p { margin: 8px 0; }
.bar {
  display: flex;
  justify-content: space-between;
  color: #888;
  font-size: 0.85rem;
}
